struct ZeroThenError(Arc<AtomicUsize>);
impl AsyncRead for ZeroThenError {
    fn poll_read(self: Pin<&mut Self>, _: &mut Context<'_>, _: &mut tokio_io::ReadBuf<'_>) -> Poll<io::Result<()>> { Poll::Pending }
}
impl AsyncWrite for ZeroThenError {
    fn poll_write(self: Pin<&mut Self>, _: &mut Context<'_>, buf: &[u8]) -> Poll<io::Result<usize>> {
        assert!(!buf.is_empty());
        if self.0.fetch_add(1, Ordering::SeqCst) == 0 { Poll::Ready(Ok(0)) }
        else { Poll::Ready(Err(io::Error::new(io::ErrorKind::Other, "second write sentinel"))) }
    }
    fn poll_flush(self: Pin<&mut Self>, _: &mut Context<'_>) -> Poll<io::Result<()>> { Poll::Ready(Ok(())) }
    fn poll_shutdown(self: Pin<&mut Self>, _: &mut Context<'_>) -> Poll<io::Result<()>> { Poll::Ready(Ok(())) }
}

#[tokio::test]
async fn zero_write_returns_write_zero() {
    let calls = Arc::new(AtomicUsize::new(0));
    let mut codec = h2::Codec::<_, Bytes>::new(ZeroThenError(calls.clone()));
    codec.buffer(frame::Settings::default().into()).unwrap();
    let error = poll_fn(|cx| codec.flush(cx)).await.unwrap_err();
    assert_eq!((error.kind(), calls.load(Ordering::SeqCst)), (io::ErrorKind::WriteZero, 1), "error={error}");
}
